  // Load everything when modal opens
  useEffect(() => {
    if (!open) return;
    (async () => {
      setLoading(true);
      try {
        const [mats] = await Promise.all([
          loadAllEntityRows({ entity: DimensionalLetterMaterial, query: { is_active: true }, sort: "sort_order", label: "Dimensional Letter materials" }),
          loadSettings(),
