export default function TabBadgeTrigger({ value, icon: Icon, label, amount, count, warn, accent, color = "purple" }) {
  const hasAmount = parseFloat(amount) > 0;
  const styles = COLOR_STYLES[color] || COLOR_STYLES.purple;
