                aria-invalid={fieldIssue("internalMortarGapInches") || undefined}
                aria-describedby={describedBy("internalMortarGapInches")}
              />
            </label>
          </div>
        )}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-2 text-xs text-gray-600">
        <div>Units: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.totalBricks) ? Math.round(c.totalBricks) : "Not saved"}</span></div>
        <div>Courses: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.numCourses) ? Math.ceil(c.numCourses) : "Not saved"}</span></div>
        <div>Material: <span className="font-semibold text-gray-900">{amt(c.materialCost)}</span></div>
        <div>Mortar: <span className="font-semibold text-gray-900">{amt(c.mortarCost)}</span></div>
        <div>Labor: <span className="font-semibold text-gray-900">{amt(c.laborCost)}</span></div>
        <div>Labor hrs: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.laborHours) ? c.laborHours.toFixed(1) : "Not saved"}</span></div>
        <div>Linear in: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.totalLinearInches) ? Math.round(c.totalLinearInches) : "Not saved"}</span></div>
        {pricingUnavailable && <div className="col-span-full text-[10px] font-semibold text-amber-700">Saved amounts (not current pricing)</div>}
        {pricingIssues.length > 0 && (
          <div role="status" className="col-span-full text-[10px] text-amber-700 space-y-0.5" id={`wall-${index}-pricing`}>
            {pricingIssues.map((issue) => <p key={`${issue.field}-${issue.code}`}>{issue.message}</p>)}
          </div>
        )}
      </div>

      <div className="flex items-center gap-2">
        <Button variant="outline" size="sm" onClick={() => setShowEditor((v) => !v)}
          aria-expanded={showEditor}
          aria-invalid={fieldIssue("shape") || undefined}
          aria-describedby={describedBy("shape")}>
          <PenLine className="w-4 h-4" aria-hidden="true" /> {showEditor ? "Hide outline" : "Wall outline"}
        </Button>
        {fieldIssue("shape") ? (
          <span className="text-xs text-amber-600">
            Outline geometry needs repair before repricing - see diagnostics above.
          </span>
        ) : !wall.shape?.segments?.length ? (
          <span className="text-xs text-amber-600">
            No outline yet - draw the wall footprint before estimating quantities.
          </span>
        ) : null}
      </div>

      {showEditor && (
        <WallShapeEditor shape={wall.shape} onChange={(shape) => set({ shape })} />
      )}
    </div>
  );
}

export default function FoundationWallsPanel({ walls = [], options = [], onChange, wallPricing = [] }) {
  const patchWall = (index, changes) =>
    onChange(walls.map((w, i) => (i === index ? { ...w, ...changes } : w)));

  const removeWall = (index) => {
    const name = walls[index]?.name || `Wall ${index + 1}`;
    if (!window.confirm(`Remove ${name}? Wall caps attached to it are retained for review.`)) return;
    onChange(walls.filter((_, i) => i !== index));
  };

  const addWall = () =>
    onChange([
      ...walls,
      { name: `Wall ${walls.length + 1}`, heightInches: 24, mortarGapInches: 0.375, offsetFraction: 0.5 },
    ]);

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <h2 className="font-semibold text-gray-900">Masonry Walls</h2>
        <Button variant="outline" size="sm" onClick={addWall}>
          <Plus className="w-4 h-4" aria-hidden="true" /> Wall
        </Button>
      </div>

      {walls.length === 0 ? (
        <div className="text-center py-8 bg-white rounded-xl border border-dashed border-gray-300 text-gray-500 text-sm">
          No walls on this section.
        </div>
      ) : (
        walls.map((wall, index) => (
          <WallRow
            key={wall.component_id || index}
            wall={wall}
            index={index}
            options={options}
            pricing={wallPricing[index]}
            onChange={patchWall}
            onRemove={removeWall}
          />
        ))
      )}
    </div>
  );
}

import { deleteEntityIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// Read-after-write grace for the post-create verify read: a create whose
// response was lost can still have landed, and an immediate empty verify
// read is not conclusive.
const VERIFY_RETRY_DELAY_MS = 700;

const canonicalRecord = (rows = []) => [...rows].sort((a, b) => {
  const aStamp = String(a?.created_date || "");
  const bStamp = String(b?.created_date || "");
  if (aStamp !== bStamp) return aStamp.localeCompare(bStamp);
  return String(a?.id || "").localeCompare(String(b?.id || ""));
})[0] || null;

function normalize(value) {
  if (Array.isArray(value)) return value.map(normalize);
  if (!value || typeof value !== "object") return value;
  return Object.keys(value).sort().reduce((out, key) => {
    out[key] = normalize(value[key]);
    return out;
  }, {});
}

function sameValue(a, b) {
  const emptyA = a === undefined || a === null || a === "";
  const emptyB = b === undefined || b === null || b === "";
  if (emptyA && emptyB) return true;
  if (!emptyA && !emptyB && Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
    return Math.abs(Number(a) - Number(b)) <= 0.000001;
  }
  // Trimmed server values must match the retry payload — backend `clean()`
  // trims most string fields on write, so a strict compare would false-negative
  // a legitimately-reused record and 409 "retry key belongs to different data".
  if (typeof a === "string" && typeof b === "string") return a.trim() === b.trim();
  return JSON.stringify(normalize(a)) === JSON.stringify(normalize(b));
}

function matchesPayload(row, payload) {
  return !!row && Object.entries(payload || {}).every(([field, value]) => sameValue(row[field], value));
}

export function newCreationRequestKey(prefix = "create") {
  const token = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `${String(prefix || "create").trim()}:${token}`;
}

export async function ensureIdempotentEntityCreate({
  entity,
  keyField = "idempotency_key",
  key,
  data,
  label = "Record",
} = {}) {
  const cleanField = String(keyField || "").trim();
  const cleanKey = String(key || "").trim();
  if (!entity?.filter || !entity?.create || !cleanField || !cleanKey) {
    throw new Error(`${label} could not initialize its retry-safe create.`);
  }

  const payload = { ...data, [cleanField]: cleanKey };
  const load = async () => {
    const rows = await entity.filter({ [cleanField]: cleanKey });
    if (!Array.isArray(rows)) throw new Error(`${label} retry state could not be verified.`);
    return rows.filter((row) => String(row?.[cleanField] || "").trim() === cleanKey);
  };

  const existing = await load();
  if (existing.length > 1) {
    throw new Error(`${label} already has multiple records with this retry key. No row was deleted; reload and review the duplicates before continuing.`);
  }
  if (existing.length === 1) {
    if (!matchesPayload(existing[0], payload)) {
      throw new Error(`${label} retry key already belongs to a record with different data. No row was changed.`);
    }
    return existing[0];
  }

  let created = null;
  let createError = null;
  try {
    created = await entity.create(payload);
  } catch (error) {
    createError = error;
  }

  let afterCreate = null;
  let verifyError = null;
  try {
    afterCreate = await load();
  } catch (error) {
    verifyError = error;
  }
  // Read-after-write lag: a create that failed at the response layer can
  // still have landed, so an immediate empty/failed verify is not conclusive.
  // Give the write a moment and re-read once before declaring the outcome
  // unknown — a retry must resolve the existing row, never create a dup.
  if ((!Array.isArray(afterCreate) || afterCreate.length === 0) && (createError || !created?.id)) {
    await sleep(VERIFY_RETRY_DELAY_MS);
    try {
      const retryRows = await load();
      if (Array.isArray(retryRows)) afterCreate = retryRows;
    } catch (error) {
      verifyError = verifyError || error;
    }
  }
  if (!Array.isArray(afterCreate)) {
    if (created?.id && matchesPayload(created, payload)) return created;
    throw new Error(`${label} create outcome could not be verified. Do not retry blindly; reload first. ${verifyError?.message || "Recovery lookup failed."}`);
  }

  if (afterCreate.length === 1) {
    // Our create returned an id but the only visible same-key row is a
    // different record — a concurrent create landed too and ours is still
    // indexing. Fail closed instead of silently orphaning our row as a dup.
    if (created?.id && String(afterCreate[0].id) !== String(created.id)) {
      throw new Error(`${label} was created concurrently more than once. No uncertain duplicate was deleted; reload and review records with this retry key.`);
    }
    if (!matchesPayload(afterCreate[0], payload)) {
      throw new Error(`${label} retry key exists but its live data does not match this create. No row was changed or deleted.`);
    }
    return afterCreate[0];
  }

  if (afterCreate.length > 1) {
    const keep = canonicalRecord(afterCreate);
    const ours = created?.id ? afterCreate.find((row) => row.id === created.id) : null;
    if (ours && ours.id !== keep?.id && matchesPayload(ours, payload)) {
      await deleteEntityIfUnchanged({
        entity,
        record: ours,
        guardFields: { [cleanField]: cleanKey },
        label: `${label} losing retry duplicate`,
      });
      const finalRows = await load();
      if (finalRows.length === 1 && finalRows[0]?.id === keep?.id && matchesPayload(finalRows[0], payload)) {
        return finalRows[0];
      }
    }
    throw new Error(`${label} was created concurrently more than once. No uncertain duplicate was deleted; reload and review records with this retry key.`);
  }

  if (created?.id && matchesPayload(created, payload)) return created;
  if (createError) {
    throw new Error(`${label} create failed and no matching record was visible on recovery read. Do not retry blindly; reload first. ${createError?.message || ""}`.trim());
  }
  throw new Error(`${label} create response could not be verified. Do not retry blindly; reload first.`);
}

const DEFAULT_PAGE_SIZE = 500;
const DEFAULT_MAX_ROWS = 50000;
const RATE_LIMIT_MAX_RETRIES = 3;
const RATE_LIMIT_BASE_DELAY_MS = 1200;

function rowIdentity(row, index) {
  const id = String(row?.id || "").trim();
  return id || `__row_${index}`;
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export function isRateLimitError(error) {
  const status = error?.status ?? error?.response?.status;
  if (status === 429) return true;
  const message = String(
    error?.message ||
    error?.response?.data?.error ||
    error?.data?.error ||
    ""
  ).toLowerCase();
  return message.includes("rate limit") || message.includes("too many requests");
}

/**
 * Retries a single SDK call when the platform returns a transient rate-limit
 * error. Uses exponential backoff so concurrent page-load calls (builder
 * reconciliation, part catalogs, section snapshots) don't all retry at once.
 */
export async function withRateLimitRetry(fn) {
  for (let attempt = 0; attempt <= RATE_LIMIT_MAX_RETRIES; attempt += 1) {
    try {
      return await fn();
    } catch (error) {
      // The request governor already retried this call with backoff; a second
      // retry loop here would multiply the delay without helping.
      if (typeof error?.ccsGovernorRetried === "number") throw error;
      if (attempt < RATE_LIMIT_MAX_RETRIES && isRateLimitError(error)) {
        await sleep(RATE_LIMIT_BASE_DELAY_MS * Math.pow(2, attempt));
        continue;
      }
      throw error;
    }
  }
}

/**
 * Load a complete estimator prerequisite catalog without relying on Base44's
 * list/filter default limit (50 rows).
 *
 * This helper is intentionally read-only. It pages the existing entity client
 * using the SDK's list/filter(sort, limit, skip) contract, fails closed on an
 * unreadable page, and de-duplicates by entity id so callers never silently
 * estimate from a partial catalog.
 *
 * Paging order defaults to ASCENDING "created_date" (not "-created_date").
 * That is deliberate: new rows append to the end of the set, so earlier
 * skip/limit pages stay stable while a full scan is in flight — a
 * newest-first order would shift every page on each concurrent insert.
 * Callers may pass any SDK sort string; it is forwarded to list/filter on
 * every page (an empty/falsy sort falls back to the SDK's own default).
 */
/**
 * @param {{
 *   entity?: any,
 *   query?: Record<string, any> | null,
 *   sort?: string | null,
 *   pageSize?: number,
 *   maxRows?: number,
 *   label?: string,
 *   limit?: number | null,
 * }} [options]
 */
// Short-TTL in-memory cache for slow-changing catalogs (jurisdiction/locality
// lists). Opt-in per call — repeated mounts of the same page stop re-reading
// the whole catalog and burning the shared rate-limit budget. Keyed per
// entity object (like inFlightReads): the query/sort/limits tuple alone is
// not unique — two entities with identical reads would otherwise share a
// cache slot and serve each other's rows.
const readCache = new WeakMap(); // entity -> Map<key, {at, rows}>
const CACHE_MAX_AGE_MS = 30000;
// Identical reads issued at the same instant (mount bursts, StrictMode double
// mounts, sibling components) share one network pass. Keyed per entity object
// so different gateways never share rows; every caller receives a copy so an
// in-place sort/splice by one consumer cannot corrupt another's result.
const inFlightReads = new WeakMap(); // entity -> Map<key, Promise<rows>>

const readCacheBucket = (entity) => {
  let bucket = readCache.get(entity);
  if (!bucket) {
    bucket = new Map();
    readCache.set(entity, bucket);
  }
  return bucket;
};

// Seed the short-TTL cache with rows fetched through a batch read so the
// per-entity loaders skip their own network call on the next mount.
export const primeEntityRowsCache = (entity, query, sort, rows) => {
  if (entity === null || (typeof entity !== "object" && typeof entity !== "function")) return;
  readCacheBucket(entity).set(JSON.stringify([query ?? null, sort, DEFAULT_PAGE_SIZE, DEFAULT_MAX_ROWS]), { at: Date.now(), rows });
};

export async function loadAllEntityRows({
  entity,
  query = null,
  sort = "created_date",
  pageSize = DEFAULT_PAGE_SIZE,
  maxRows = DEFAULT_MAX_ROWS,
  label = "Estimator prerequisite catalog",
  cacheTtlMs = 0,
  // (#403) `limit` bounds the total rows returned for callers that only need a
  // window (e.g. "the 50 newest"), not a verified-complete catalog. Reaching
  // the bound is a normal truncation — unlike `maxRows`, which stays a
  // runaway-scan safety net and still throws when a full scan would pass it.
  limit = null,
} = {}) {
  const parsedLimit = limit == null ? null : Math.floor(Number(limit));
  const safeLimit = Number.isFinite(parsedLimit) && parsedLimit > 0 ? parsedLimit : null;
  const canShare = entity !== null && (typeof entity === "object" || typeof entity === "function");
  const cacheKey = cacheTtlMs > 0 && canShare ? JSON.stringify([query, sort, pageSize, safeLimit ?? maxRows]) : null;
  if (cacheKey) {
    const hit = readCache.get(entity)?.get(cacheKey);
    if (hit && Date.now() - hit.at < Math.min(cacheTtlMs, CACHE_MAX_AGE_MS)) return [...hit.rows];
  }
  const hasFilter = query && typeof query === "object";
  const reader = hasFilter ? entity?.filter : entity?.list;
  if (typeof reader !== "function") {
    throw new Error(`${label} could not initialize its paged read.`);
  }

  const safePageSize = Math.max(1, Math.min(500, Number(pageSize) || DEFAULT_PAGE_SIZE));
  // A bounded read never fetches a page larger than the rows still wanted —
  // `limit: 50` costs exactly one 50-row request, not a 500-row page.
  const safeMaxRows = safeLimit ?? Math.max(safePageSize, Number(maxRows) || DEFAULT_MAX_ROWS);

  // Join an identical read already in flight instead of starting a second
  // paged scan for the same data. Non-object entities skip sharing.
  const flightKey = JSON.stringify([hasFilter ? "filter" : "list", query ?? null, sort ?? null, safePageSize, safeMaxRows]);
  if (canShare) {
    const existing = inFlightReads.get(entity)?.get(flightKey);
    if (existing) return existing.then((rows) => [...rows]);
  }

  const readPromise = (async () => {
    const collected = [];
    const seen = new Set();
    let skip = 0;

    while (skip < safeMaxRows) {
      const pageLimit = Math.min(safePageSize, safeMaxRows - skip);
      const page = await withRateLimitRetry(() =>
        hasFilter
          ? entity.filter(query, sort || undefined, pageLimit, skip)
          : entity.list(sort || undefined, pageLimit, skip)
      );

      if (!Array.isArray(page)) {
        throw new Error(`${label} could not be verified completely. Estimating was blocked rather than using a partial catalog.`);
      }

      for (let index = 0; index < page.length; index += 1) {
        const row = page[index];
        const key = rowIdentity(row, skip + index);
        if (seen.has(key)) continue;
        seen.add(key);
        collected.push(row);
      }

      if (page.length < pageLimit) {
        if (cacheKey) readCacheBucket(entity).set(cacheKey, { at: Date.now(), rows: collected });
        return collected;
      }
      skip += pageLimit;
    }

    if (safeLimit != null) {
      if (cacheKey) readCacheBucket(entity).set(cacheKey, { at: Date.now(), rows: collected });
      return collected;
    }
    throw new Error(`${label} exceeds the ${safeMaxRows.toLocaleString()}-record estimator safety limit.`);
  })();

  if (!canShare) return readPromise;
  let flightBucket = inFlightReads.get(entity);
  if (!flightBucket) {
    flightBucket = new Map();
    inFlightReads.set(entity, flightBucket);
  }
  flightBucket.set(flightKey, readPromise);
  try {
    const rows = await readPromise;
    return [...rows];
  } finally {
    if (flightBucket.get(flightKey) === readPromise) flightBucket.delete(flightKey);
  }
}

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Copy, LayoutTemplate, BookmarkPlus, Link2, Loader2 } from "lucide-react";
import { createEstimateReadOnlyShareLink } from "./moduleProjectActions";

// Shared per-module estimator affordances (#78 save-as-copy, #79 templates,
// #88 read-only share link). Mounts next to an existing save control; each
// button is rendered only when its handler/feature applies — the share link
// needs a live estimate id, so standalone drafts simply do not offer it.
export default function ModuleActionBar({
  onTemplates,
  onSaveAsTemplate,
  onSaveAsCopy,
  estimateId,
  saving,
  size = "sm",
}) {
  const [sharing, setSharing] = useState(false);

  const share = async () => {
    if (!estimateId || sharing) return;
    setSharing(true);
    try {
      const url = await createEstimateReadOnlyShareLink({ estimateId });
      await navigator.clipboard.writeText(url);
      alert("Read-only link copied to clipboard:\n" + url);
    } catch (e) {
      console.error(e);
      alert("Share link failed: " + (e?.message || e));
    } finally {
      setSharing(false);
    }
  };

  const disabled = Boolean(saving);
  return (
    <>
      {onTemplates ? (
        <Button type="button" variant="outline" size={size} onClick={onTemplates} disabled={disabled}>
          <LayoutTemplate className="w-4 h-4 mr-1" aria-hidden="true" /> Templates
        </Button>
      ) : null}
      {onSaveAsTemplate ? (
        <Button type="button" variant="outline" size={size} onClick={onSaveAsTemplate} disabled={disabled}>
          <BookmarkPlus className="w-4 h-4 mr-1" aria-hidden="true" /> Save as Template
        </Button>
      ) : null}
      {onSaveAsCopy ? (
        <Button type="button" variant="outline" size={size} onClick={onSaveAsCopy} disabled={disabled}>
          <Copy className="w-4 h-4 mr-1" aria-hidden="true" /> Save As Copy
        </Button>
      ) : null}
      {estimateId ? (
        <Button type="button" variant="outline" size={size} onClick={share} disabled={disabled || sharing} title="Copy a read-only link to this estimate">
          {sharing ? <Loader2 className="w-4 h-4 mr-1 animate-spin" aria-hidden="true" /> : <Link2 className="w-4 h-4 mr-1" aria-hidden="true" />} Share Link
        </Button>
      ) : null}
    </>
  );
}

import { ensureIdempotentEntityCreate, newCreationRequestKey } from "@/components/estimator/idempotentEntityCreate";
import { getSessionToken } from "@/components/auth/EmailGate";
import { invokePortal } from "@/components/portal/PortalPanel";

// Fields that must never be cloned into a new project row — identity and
// server-managed values. The copy keeps every editable payload field while a
// fresh identity and a fresh creation_request_key make it a real new record.
const STRIP_ON_COPY = new Set([
  "id",
  "created_date",
  "updated_date",
  "created_by",
  "created_by_id",
  "is_sample",
  "creation_request_key",
  "idempotency_key",
]);

// Clone a module's save payload into a brand-new project record (#78). The
// caller passes its normal persisted payload; we strip identity/system fields,
// force "(Copy)" onto the name, and create through the same
// signature-stable retry-key + ensureIdempotentEntityCreate flow Foundation
// uses so a double-click or lost response can never produce duplicate copies.
export async function saveModuleProjectCopy({
  entity,
  payload,
  attemptRef,
  keyPrefix,
  nameField = "project_name",
  baseName,
  extraData = {},
  label = "Project copy",
}) {
  const copyData = { ...payload };
  for (const key of STRIP_ON_COPY) delete copyData[key];
  copyData[nameField] = `${baseName || copyData[nameField] || "Estimate"} (Copy)`;
  Object.assign(copyData, extraData);

  const signature = JSON.stringify(copyData);
  if (attemptRef.current.signature !== signature) {
    attemptRef.current = {
      signature,
      key: newCreationRequestKey(keyPrefix),
    };
  }

  const copy = await ensureIdempotentEntityCreate({
    entity,
    keyField: "creation_request_key",
    key: attemptRef.current.key,
    data: copyData,
    label,
  });
  if (!copy?.id) throw new Error(`${label} could not be verified.`);
  return copy;
}

// Create (or reuse) a read-only staff_view portal link for an estimate and
// return its absolute URL (#88). The link is view-only end-to-end: the portal
// bootstrap closes every non-'customer' mutation on that kind server-side.
export async function createEstimateReadOnlyShareLink({ estimateId, label } = {}) {
  const id = String(estimateId || "").trim();
  if (!id) throw new Error("An estimate id is required to share a read-only link.");
  const sessionToken = getSessionToken();
  if (!sessionToken) throw new Error("Sign-in required.");
  const data = await invokePortal(sessionToken, {
    action: "create_link",
    kind: "staff_view",
    estimate_id: id,
    label,
    creation_request_key: crypto.randomUUID(),
  });
  const token = data?.token || data?.link?.token;
  if (!token) throw new Error("The share link could not be verified.");
  return `${window.location.origin}/customerportal?token=${encodeURIComponent(token)}`;
}

import { useEffect, useRef, useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Trash2 } from "lucide-react";
import { deleteModuleTemplate, listModuleTemplates, saveModuleTemplate } from "./moduleTemplateService";

// Generic save/load/delete template dialog keyed by module (#79). The caller
// supplies how the live project state becomes a template payload
// (buildTemplateData) and how a row is described in the list (describeTemplate);
// the dialog owns the idempotent-save retry key exactly like the Foundation
// implementation it is generalized from.
export default function ModuleTemplateDialog({
  open,
  mode,
  onClose,
  project,
  onApply,
  moduleKey,
  title = "Module",
  buildTemplateData,
  describeTemplate,
}) {
  const [templates, setTemplates] = useState([]);
  const [name, setName] = useState("");
  const [busy, setBusy] = useState(false);
  const saveAttemptRef = useRef({ signature: "", key: "" });

  useEffect(() => {
    if (!open) return;
    saveAttemptRef.current = { signature: "", key: "" };
    if (mode !== "load") return;
    listModuleTemplates({ moduleKey }).then((rows) => setTemplates(rows || []));
  }, [open, mode, moduleKey]);

  const save = async () => {
    if (!name.trim()) return;
    setBusy(true);
    try {
      const data = {
        template_name: name.trim(),
        module_key: moduleKey,
        project_data: buildTemplateData ? buildTemplateData(project) : project,
      };
      const signature = JSON.stringify(data);
      if (saveAttemptRef.current.signature !== signature) {
        saveAttemptRef.current = {
          signature,
          key: `${moduleKey}_template_save:${crypto.randomUUID?.() || `${Date.now()}-${Math.random()}`}`,
        };
      }
      await saveModuleTemplate({
        moduleKey,
        idempotencyKey: saveAttemptRef.current.key,
        data,
        label: `${title} template`,
      });
      setName("");
      saveAttemptRef.current = { signature: "", key: "" };
      onClose();
    } finally {
      setBusy(false);
    }
  };

  const remove = async (t) => {
    if (!window.confirm(`Delete template "${t.template_name || "Untitled"}"?`)) return;
    try {
      await deleteModuleTemplate(t.id, `${title} template`);
      setTemplates((prev) => prev.filter((x) => x.id !== t.id));
    } catch {
      // leave the template in the list when the delete fails
    }
  };

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="max-w-[520px]">
        <DialogHeader>
          <DialogTitle className="text-[15px]">
            {mode === "save" ? "Save as Template" : `${title} Templates`}
          </DialogTitle>
        </DialogHeader>

        {mode === "save" ? (
          <div className="space-y-3">
            <label className="text-[11px] text-gray-500 block">
              Template name
              <input
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder={`e.g. Standard ${title} setup`}
                className="w-full h-[30px] px-2 border border-gray-300 rounded-sm text-[12px] focus:outline-none focus:border-red-400"
              />
            </label>
            <div className="flex justify-end gap-2">
              <button type="button" onClick={onClose} className="h-[30px] px-3 border border-gray-300 rounded-sm text-[12px]">
                Cancel
              </button>
              <button
                type="button"
                onClick={save}
                disabled={busy}
                className="h-[30px] px-4 rounded-sm bg-lime-300 border border-lime-400 text-[12px] font-bold text-gray-800 disabled:opacity-60"
              >
                Save Template
              </button>
            </div>
          </div>
        ) : templates.length === 0 ? (
          <p className="text-[12px] text-gray-500 py-4">No {title.toLowerCase()} templates saved yet.</p>
        ) : (
          <div className="divide-y divide-gray-200 max-h-[320px] overflow-y-auto">
            {templates.map((t) => (
              <div key={t.id} className="flex items-center gap-2 py-2">
                <div className="flex-1">
                  <div className="text-[12px] font-semibold text-gray-800">{t.template_name}</div>
                  <div className="text-[11px] text-gray-500">
                    {describeTemplate ? describeTemplate(t) : `${Object.keys(t.project_data || {}).length} fields`}
                  </div>
                </div>
                <button
                  type="button"
                  onClick={() => {
                    onApply(t.project_data || {});
                    onClose();
                  }}
                  className="h-[26px] px-3 rounded-sm bg-white border border-gray-300 text-[11px] font-semibold text-gray-700"
                >
                  Apply
                </button>
                <button type="button" onClick={() => remove(t)} className="text-gray-400 hover:text-red-600">
                  <Trash2 className="w-4 h-4" aria-hidden="true" />
                </button>
              </div>
            ))}
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import React, { useEffect, useMemo, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import { TrendingUp, Info } from "lucide-react";
import { applyMarkups, parseVolumeDiscountBrackets, parseVolumeDiscountCategories } from "./markupEngine";
import { loadCustomerPricingConfig } from "./savedCustomerPricing";
import TierBadge, { getTierTheme } from "./TierBadge";

const fmt = (n) => "$" + (Number(n) || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

/**
 * Reusable Customer Pricing Summary tab for every estimator.
 *
 * Props:
 *   project      — the in-memory project object with totals
 *   categorize   — function(project) => [{ module, label, cost, category_key }]
 *   accentColor  — tailwind color name (purple, red, green, blue, orange) for the header
 *   onTierChange — optional callback. When provided, selected tier becomes the Builder's saved tier on next save.
 *   onApplyTier  — optional explicit-apply callback for Builders that already have a working manual pricing mode.
 */
export default function CustomerPricingTab({ project, categorize, accentColor = "slate", onTierChange, onApplyTier }) {
  const [tiers, setTiers] = useState([]);
  const [categories, setCategories] = useState([]);
  const [settings, setSettings] = useState([]);
  const [tierNumber, setTierNumber] = useState(1);
  const [customerDefaultTier, setCustomerDefaultTier] = useState(1);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState("");

  useEffect(() => {
    let active = true;
    (async () => {
      if (active) {
        setLoading(true);
        setLoadError("");
      }
      try {
        const config = await loadCustomerPricingConfig(project);
        if (!active) return;
        setTiers(config.tiers || []);
        setCategories(config.categories || []);
        setSettings(config.settings || []);
        setCustomerDefaultTier(Number(config.customer?.pricing_tier) || 1);
        setTierNumber(Number(config.defaultTierNumber) || 1);
      } catch (e) {
        console.error("CustomerPricingTab load error:", e);
        if (active) setLoadError(e?.message || "Customer pricing configuration could not be verified.");
      }
      if (active) setLoading(false);
    })();
    return () => { active = false; };
  }, [project?.customer_id]);

  useEffect(() => {
    const savedTier = Number(project?.customer_pricing?.tier_number || project?.customer_pricing_tier);
    if (savedTier > 0 && tiers.some((tier) => Number(tier.tier_number) === savedTier)) {
      setTierNumber(savedTier);
    }
  }, [project?.customer_pricing?.tier_number, project?.customer_pricing_tier, tiers]);

  const selectedTier = useMemo(
    () => tiers.find((t) => t.tier_number === Number(tierNumber)) || tiers[0],
    [tiers, tierNumber]
  );

  const lines = useMemo(() => {
    try {
      return categorize(project) || [];
    } catch (e) {
      console.error("categorize error:", e);
      return [];
    }
  }, [project, categorize]);

  const markupResult = useMemo(() => {
    const brackets = parseVolumeDiscountBrackets(settings);
    const eligibleCategoryKeys = parseVolumeDiscountCategories(settings);
    const categoryFlags = Object.fromEntries(
      (categories || []).map((c) => [c?.category_key, c?.volume_discount_eligible]).filter(([k]) => k),
    );
    return applyMarkups(lines, selectedTier, { brackets, eligibleCategoryKeys, categoryFlags });
  }, [lines, selectedTier, settings, categories]);

  const categoryNameByKey = useMemo(
    () => Object.fromEntries(categories.map((c) => [c.category_key, c.category_name])),
    [categories]
  );

  // Group lines by category for display
  const byCategory = useMemo(() => {
    const map = {};
    markupResult.lines.forEach((l) => {
      const key = l.category_key;
      if (!map[key]) {
        map[key] = { name: categoryNameByKey[key] || key, lines: [], rawTotal: 0, finalTotal: 0 };
      }
      map[key].lines.push(l);
      map[key].rawTotal += l.cost;
      map[key].finalTotal += l.final_cost;
    });
    return map;
  }, [markupResult, categoryNameByKey]);

  const theme = getTierTheme(tierNumber);

  if (loading) {
    return (
      <Card className="bg-white border-0 shadow-sm">
        <CardContent className="p-8 text-center text-slate-500">Loading pricing tiers…</CardContent>
      </Card>
    );
  }

  if (loadError) {
    return (
      <Card className="bg-red-50 border-red-200">
        <CardContent className="p-6 text-sm text-red-900">
          <div className="flex items-start gap-2">
            <Info className="w-4 h-4 mt-0.5 flex-shrink-0" />
            <div>
              <p className="font-medium mb-1">Customer pricing unavailable</p>
              <p className="text-xs">{loadError}</p>
              <p className="text-xs mt-1">Tier-based customer pricing is not treated as missing or recalculated from fallback configuration while these pricing records cannot be verified.</p>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (tiers.length === 0) {
    return (
      <Card className="bg-amber-50 border-amber-200">
        <CardContent className="p-6 text-sm text-amber-900">
          <div className="flex items-start gap-2">
            <Info className="w-4 h-4 mt-0.5 flex-shrink-0" />
            <div>
              <p className="font-medium mb-1">No pricing tiers configured</p>
              <p className="text-xs">
                Visit <span className="font-semibold">Admin → Markups</span> to set up tier markups before using this view.
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (lines.length === 0) {
    return (
      <Card className="bg-white border-0 shadow-sm">
        <CardContent className="p-8 text-center text-slate-500 text-sm">
          Add items to the project to see customer pricing.
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      {/* Tier selector */}
      <Card className="bg-white border-0 shadow-sm">
        <CardHeader className="pb-3">
          <CardTitle className="text-lg flex items-center gap-2">
            <TrendingUp className={`w-5 h-5 text-${accentColor}-600`} />
            Customer Pricing Summary
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="flex flex-wrap items-end gap-4">
            <div className="min-w-[260px] flex-1">
              <Label className="text-xs mb-1.5 block">Pricing Tier</Label>
              <Select
                value={String(tierNumber)}
                onValueChange={(v) => {
                  const nextTier = Number(v);
                  setTierNumber(nextTier);
                  onTierChange?.(nextTier);
                }}
              >
                <SelectTrigger className="h-10">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {tiers.map((t) => (
                    <SelectItem key={t.id} value={String(t.tier_number)}>
                      Tier {t.tier_number} — {t.tier_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className={`flex items-center gap-3 px-4 py-2 rounded-xl ${theme.soft} ${theme.softText} border ${theme.accent}`}>
              <TierBadge tierNumber={tierNumber} />
              <div>
                <p className="text-xs opacity-75">Selected Tier</p>
                <p className="font-semibold text-sm">{selectedTier?.tier_name || `Tier ${tierNumber}`}</p>
              </div>
              {onApplyTier && (
                <button
                  type="button"
                  onClick={() => onApplyTier(tierNumber)}
                  className="ml-auto h-8 px-3 rounded border border-current/25 bg-white/80 text-xs font-semibold hover:bg-white"
                >
                  Use Tier {tierNumber}
                </button>
              )}
            </div>
          </div>
          {selectedTier?.description && (
            <p className="text-xs text-slate-500 italic">{selectedTier.description}</p>
          )}
        </CardContent>
      </Card>

      {/* Cost breakdown by category */}
      <Card className="bg-white border-0 shadow-sm">
        <CardHeader className="pb-3">
          <CardTitle className="text-base">Marked-Up Breakdown by Category</CardTitle>
        </CardHeader>
        <CardContent className="overflow-x-auto p-0">
          <table className="w-full text-sm">
            <thead className="bg-slate-50 text-slate-600 text-xs">
              <tr>
                <th className="text-left px-4 py-2 font-medium">Description</th>
                <th className="text-right px-4 py-2 font-medium">Cost</th>
                <th className="text-right px-4 py-2 font-medium">Markup</th>
                <th className="text-right px-4 py-2 font-medium">Vol Disc</th>
                <th className="text-right px-4 py-2 font-medium">Customer Price</th>
              </tr>
            </thead>
            <tbody>
              {Object.entries(byCategory).map(([catKey, group]) => (
                <React.Fragment key={catKey}>
                  <tr className="bg-slate-100/70">
                    <td colSpan={5} className="px-4 py-2 font-semibold text-slate-700 text-xs uppercase tracking-wide">
                      {group.name}
                      <span className="ml-2 text-slate-500 font-normal normal-case tracking-normal">
                        — {fmt(group.rawTotal)} cost → <span className="font-semibold text-slate-700">{fmt(group.finalTotal)}</span>
                      </span>
                    </td>
                  </tr>
                  {group.lines.map((l, i) => (
                    <tr key={`${catKey}-${i}`} className="border-t border-slate-100 hover:bg-slate-50/50">
                      <td className="px-4 py-2">{l.label}</td>
                      <td className="px-4 py-2 text-right tabular-nums text-slate-500">{fmt(l.cost)}</td>
                      <td className="px-4 py-2 text-right tabular-nums">
                        {(l.markup_multiplier * 100).toFixed(1)}%
                      </td>
                      <td className="px-4 py-2 text-right tabular-nums">
                        {l.volume_discount_applied > 0 ? `${l.volume_discount_applied}%` : "—"}
                      </td>
                      <td className="px-4 py-2 text-right tabular-nums font-semibold">{fmt(l.final_cost)}</td>
                    </tr>
                  ))}
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </CardContent>
      </Card>

      {/* Grand total card */}
      <Card className={`border-2 ${theme.accent} ${theme.soft}`}>
        <CardContent className="p-5 space-y-2">
          <div className="flex justify-between text-sm text-slate-600">
            <span>Internal cost subtotal</span>
            <span className="tabular-nums">{fmt(markupResult.totals.raw_subtotal)}</span>
          </div>
          <div className="flex justify-between text-sm text-slate-600">
            <span>After Tier {tierNumber} markup</span>
            <span className="tabular-nums">{fmt(markupResult.totals.marked_subtotal)}</span>
          </div>
          {markupResult.totals.volume_discount_pct > 0 && (
            <div className="flex justify-between text-sm text-amber-700">
              <span>Volume discount ({markupResult.totals.volume_discount_pct}%)</span>
              <span className="tabular-nums">
                −{fmt(markupResult.totals.marked_subtotal - markupResult.totals.grand_total)}
              </span>
            </div>
          )}
          <div className={`border-t pt-2 flex justify-between items-center ${theme.softText}`}>
            <span className="text-lg font-bold">Customer Price</span>
            <span className="text-2xl font-bold tabular-nums">{fmt(markupResult.totals.grand_total)}</span>
          </div>
          {markupResult.totals.raw_subtotal > 0 && (
            <p className="text-xs text-slate-500 pt-1">
              Margin: <span className="font-semibold">{fmt(markupResult.totals.grand_total - markupResult.totals.raw_subtotal)}</span>
              {" "}({(((markupResult.totals.grand_total - markupResult.totals.raw_subtotal) / markupResult.totals.grand_total) * 100).toFixed(1)}% of customer price)
            </p>
          )}
        </CardContent>
      </Card>

      <Card className="bg-blue-50 border-blue-200">
        <CardContent className="p-3 text-xs text-blue-900 flex items-start gap-2">
          <Info className="w-4 h-4 flex-shrink-0 mt-0.5" />
          <span>
            Markups and volume discount brackets are configured in <strong>Admin → Markups</strong>.
            {onTierChange ? (
              <> Tier {tierNumber} will be saved with this Builder the next time you save it. Customer default: Tier {customerDefaultTier}.</>
            ) : onApplyTier ? (
              <> Preview tiers freely, then choose <strong>Use Tier {tierNumber}</strong> to replace this Builder's manual sell-price mode. Customer default: Tier {customerDefaultTier}.</>
            ) : (
              <> This view is currently preview-only.</>
            )}
          </span>
        </CardContent>
      </Card>
    </div>
  );
}

// Pure utility functions for applying tier markups + volume discounts to project costs.
// Does NOT mutate project entities — produces a marked-up summary breakdown.

/**
 * Get a tier's markup multiplier for a given category_key.
 * Falls back to 1.0 (no markup) when the value is missing or non-positive.
 * Values between 0 and 1 are valid discount markups and are honored — only
 * ≤0 and non-numeric entries are treated as "not configured".
 */
export function getMarkup(tier, categoryKey) {
  if (!tier || !tier.markups) return 1.0;
  const v = tier.markups[categoryKey];
  return typeof v === 'number' && v > 0 ? v : 1.0;
}

/**
 * Parse volume discount brackets from Settings records.
 * Returns array of {min, pct} sorted high-to-low so we can pick the highest qualifying bracket.
 */
export function parseVolumeDiscountBrackets(settings) {
  const get = (name) => {
    const s = settings.find(x => x.setting_name === name);
    return s ? parseFloat(s.setting_value) : null;
  };
  const brackets = [];
  for (let i = 1; i <= 4; i++) {
    const min = get(`volume_discount_bracket_${i}_min`);
    const pct = get(`volume_discount_bracket_${i}_pct`);
    if (min !== null && pct !== null) brackets.push({ min, pct });
  }
  return brackets.sort((a, b) => b.min - a.min);
}

/**
 * Parse the list of category keys eligible for volume discount.
 */
export function parseVolumeDiscountCategories(settings) {
  const s = settings.find(x => x.setting_name === 'volume_discount_applies_to');
  if (!s) return [];
  return s.setting_value.split(',').map(x => x.trim()).filter(Boolean);
}

/**
 * Given an eligible subtotal, find the highest qualifying volume discount %.
 */
export function getVolumeDiscountPct(eligibleSubtotal, brackets) {
  for (const b of brackets) {
    if (eligibleSubtotal >= b.min) return b.pct;
  }
  return 0;
}

/**
 * Apply tier markup + volume discount to a list of cost lines.
 *
 * @param {Array<{label, cost, category_key, module}>} lines
 * @param {Object} tier - MarkupTier record
 * @param {Object} settings - { brackets, eligibleCategoryKeys }
 * @returns {Object} { lines: [...withMarkupApplied], totals: {...} }
 */
// Skip-recompute memo (#414): identical line/tier objects with identical
// settings content return the last result without re-running the markup
// waterfall. WeakMap on lines (a new array = new payload = fresh compute).
const _applyCache = new WeakMap();

export function applyMarkups(lines, tier, settings) {
  if (!lines || typeof lines !== "object") return _applyMarkupsComputed(lines, tier, settings);
  const settingsKey = JSON.stringify(settings || {});
  let byTier = _applyCache.get(lines);
  const hit = byTier?.get(tier);
  if (hit && hit.key === settingsKey) return hit.out;
  const out = _applyMarkupsComputed(lines, tier, settings);
  if (!byTier) { byTier = new Map(); _applyCache.set(lines, byTier); }
  byTier.set(tier, { key: settingsKey, out });
  return out;
}

function _applyMarkupsComputed(lines, tier, settings) {
  const { brackets = [], eligibleCategoryKeys = [], categoryFlags = {} } = settings || {};
  const isDiscountEligible = (key) => eligibleCategoryKeys.includes(key) && categoryFlags[key] !== false;

  // First pass: compute marked-up cost per line (no volume discount yet)
  const marked = lines.map(line => {
    const cost = Number(line.cost) || 0;
    const markup = getMarkup(tier, line.category_key);
    const markedCost = cost * markup;
    return {
      ...line,
      cost,
      markup_multiplier: markup,
      marked_up_cost: markedCost,
    };
  });

  // Compute eligible subtotal for volume discount
  const eligibleSubtotal = marked
    .filter(l => isDiscountEligible(l.category_key))
    .reduce((sum, l) => sum + l.marked_up_cost, 0);

  const volumeDiscountPct = getVolumeDiscountPct(eligibleSubtotal, brackets);
  const volumeDiscountFactor = 1 - (volumeDiscountPct / 100);

  // Second pass: apply volume discount only to eligible lines
  const finalLines = marked.map(line => {
    const isEligible = isDiscountEligible(line.category_key);
    const final = isEligible ? line.marked_up_cost * volumeDiscountFactor : line.marked_up_cost;
    return {
      ...line,
      volume_discount_applied: isEligible ? volumeDiscountPct : 0,
      final_cost: final,
    };
  });

  const rawSubtotal = finalLines.reduce((s, l) => s + l.cost, 0);
  const markedSubtotal = finalLines.reduce((s, l) => s + l.marked_up_cost, 0);
  const grandTotal = finalLines.reduce((s, l) => s + l.final_cost, 0);

  // Readability merge: collapse lines sharing a category_key into one row.
  // Same-category lines always share markup multiplier + discount eligibility,
  // so summing cost fields is exact. Per-item detail stays in detail_lines.
  const mergedLines = [];
  const byKey = new Map();
  for (const l of finalLines) {
    const key = l.category_key || "";
    const existing = byKey.get(key);
    if (!existing) {
      const g = { ...l, merged_count: 1, base_label: l.label };
      byKey.set(key, g);
      mergedLines.push(g);
    } else {
      existing.merged_count += 1;
      existing.cost += l.cost;
      existing.marked_up_cost += l.marked_up_cost;
      existing.final_cost += l.final_cost;
      existing.label = `${existing.base_label} (+${existing.merged_count - 1} merged)`;
    }
  }

  return {
    lines: mergedLines,
    detail_lines: finalLines,
    totals: {
      raw_subtotal: rawSubtotal,
      marked_subtotal: markedSubtotal,
      eligible_subtotal: eligibleSubtotal,
      volume_discount_pct: volumeDiscountPct,
      grand_total: grandTotal,
    },
  };
}

/**
 * Cost-Plus pricing engine — alternative to applyMarkups().
 *
 * Pipeline (per line):
 *   1. category_markup_pct (optional)  → cost × (1 + pct/100)
 *   2. labor_multiplier                → applied only to lines flagged as labor
 *   3. overhead_percent                → flat % on the marked subtotal
 *   4. profit_percent                  → flat % on the post-overhead subtotal
 *
 * @param {Array<{label, cost, category_key, module, is_labor?}>} lines
 * @param {Object} config - CostPlusConfig record
 * @returns {Object} { lines: [...], totals: {...} }
 */
export function applyCostPlus(lines, config) {
  const cfg = config || {};
  const laborMult = Number(cfg.labor_multiplier) || 1;
  const overheadPct = Number(cfg.overhead_percent) || 0;
  const profitPct = Number(cfg.profit_percent) || 0;
  const catMarkups = cfg.category_markups || {};

  // 1+2: per-line category markup, then labor burden on labor lines
  const marked = lines.map(line => {
    const cost = Number(line.cost) || 0;
    const catPct = Number(catMarkups[line.category_key]) || 0;
    const afterCatMarkup = cost * (1 + catPct / 100);
    const afterBurden = line.is_labor ? afterCatMarkup * laborMult : afterCatMarkup;
    return {
      ...line,
      cost,
      category_markup_pct: catPct,
      labor_burden_applied: line.is_labor ? laborMult : 1,
      marked_up_cost: afterBurden,
    };
  });

  const markedSubtotal = marked.reduce((s, l) => s + l.marked_up_cost, 0);
  const overheadAmount = markedSubtotal * (overheadPct / 100);
  const afterOverhead = markedSubtotal + overheadAmount;
  const profitAmount = afterOverhead * (profitPct / 100);
  const grandTotal = afterOverhead + profitAmount;

  // Distribute overhead + profit proportionally so each line still has a "final_cost"
  const totalLift = markedSubtotal > 0 ? grandTotal / markedSubtotal : 1;
  const finalLines = marked.map(line => ({
    ...line,
    volume_discount_applied: 0,
    final_cost: line.marked_up_cost * totalLift,
  }));

  const rawSubtotal = finalLines.reduce((s, l) => s + l.cost, 0);

  return {
    lines: finalLines,
    totals: {
      raw_subtotal: rawSubtotal,
      marked_subtotal: markedSubtotal,
      overhead_pct: overheadPct,
      overhead_amount: overheadAmount,
      profit_pct: profitPct,
      profit_amount: profitAmount,
      grand_total: grandTotal,
    },
  };
}
/**
 * Target-margin price calculator ("price for X% margin").
 * margin% is the share of the SALE that is profit: price = cost / (1 - margin).
 * Differs from markup-on-cost: a 50% margin requires a 100% markup.
 * Returns 0 for a non-positive cost; null for invalid margins (>=100 or <0).
 */
export function priceForTargetMargin(cost, marginPct) {
  const c = Number(cost);
  const m = Number(marginPct);
  if (!Number.isFinite(c) || c <= 0) return 0;
  if (!Number.isFinite(m) || m < 0 || m >= 100) return null;
  return c / (1 - m / 100);
}

// Extracts cost lines from each module's project records and tags them
// with the proper category_key for tier-markup application.
//
// Mapping (from user's tier sheet):
//   Channel/Raceway/Capsule letter purchases  -> outsourced_fab
//   Dimensional Letter substrate (material)   -> substrates
//   Dimensional Letter paint materials        -> outsourced_fab
//   Dimensional Letter fab labor (CNC+paint)  -> inhouse_labor
//   Channel Letter install labor              -> inhouse_labor
//   Install materials/supplies (hardware)     -> outsourced_fab
//   Equipment rental (lifts)                  -> outsourced_services
//   Concrete + rebar materials                -> outsourced_fab
//   Foundation labor                          -> inhouse_labor
//   Poles                                     -> outsourced_fab
//   Foundation equipment rental               -> outsourced_services
//   Brick/stone material                      -> outsourced_fab
//   Masonry outsourced labor                  -> outsourced_services
//   Mortar + supplies                         -> outsourced_fab
//   Paint Estimator materials                 -> outsourced_fab
//   Paint Estimator labor                     -> inhouse_labor
//   Laser machine time                        -> machine_time
//   Laser labor                               -> inhouse_labor
//   Laser materials                           -> substrates
//   CNC machine time                          -> machine_time
//   CNC labor                                 -> inhouse_labor
//   CNC materials                             -> substrates
//   Metal Fab material                        -> substrates
//   Metal Fab labor                           -> inhouse_labor

const num = (v) => Number(v) || 0;

// Per-project memoization (#412): categorize output depends only on the
// project payload. A WeakMap keyed on the project object skips recompute when
// React re-renders pass the same object, and entries GC with the object.
const _catCache = new WeakMap();
const _catMemo = (p, compute) => {
  if (!p || typeof p !== "object") return compute(p);
  let byFn = _catCache.get(p);
  if (byFn && byFn.has(compute)) return byFn.get(compute);
  const out = compute(p);
  if (!byFn) { byFn = new Map(); _catCache.set(p, byFn); }
  byFn.set(compute, out);
  return out;
};

function _impl_categorizeChannelLetterProject(p) {
  if (!p) return [];
  const lines = [];

  // 1. Letter purchases - check each letter type
  (p.letter_purchases || []).forEach((lp) => {
    const isDimensional = lp.letter_type === 'dimensional_letters';
    const total = num(lp.total_cost);
    if (total <= 0) return;

    if (isDimensional && lp.fab_config) {
      // Dimensional: split into material vs labor using fab_config if present
      const matCost = num(lp.fab_config.material_cost) + num(lp.fab_config.paint_material_cost);
      const laborCost = num(lp.fab_config.cnc_labor_cost) + num(lp.fab_config.paint_labor_cost);
      if (matCost > 0) {
        lines.push({ module: 'channel_letter', label: `Dimensional Letter Material — ${lp.description || ''}`, cost: matCost, category_key: 'substrates' });
      }
      if (laborCost > 0) {
        lines.push({ module: 'channel_letter', label: `Dimensional Letter Fab Labor — ${lp.description || ''}`, cost: laborCost, category_key: 'inhouse_labor' });
      }
      const remainder = total - matCost - laborCost;
      if (remainder > 0.01) {
        lines.push({ module: 'channel_letter', label: `Dimensional Letter (other) — ${lp.description || ''}`, cost: remainder, category_key: 'substrates' });
      }
    } else if (isDimensional) {
      // Dimensional with no fab_config breakdown — categorize whole as substrates (material side)
      lines.push({ module: 'channel_letter', label: `Dimensional Letters — ${lp.description || ''}`, cost: total, category_key: 'substrates' });
    } else {
      // Channel / Raceway / Capsule / Logo = outsourced fab
      lines.push({ module: 'channel_letter', label: `Letter Purchase — ${lp.description || lp.letter_type}`, cost: total, category_key: 'outsourced_fab' });
    }
  });

  // 1b. Letter-level fees
  // Delivery doesn't apply when every product is dimensional (matches lettersCalculator)
  const onlyDimensional = (p.letter_purchases || []).length > 0 &&
    (p.letter_purchases || []).every(lp => lp.letter_type === 'dimensional_letters');
  const letterFees =
    (onlyDimensional ? 0 : num(p.letters_delivery_fee)) + num(p.letters_design_fee) +
    num(p.letters_install_supplies_fee) + num(p.letters_permitting_fee) +
    num(p.letters_other_fee);
  if (letterFees > 0) {
    lines.push({ module: 'channel_letter', label: 'Letter Fees (delivery/design/permit/etc.)', cost: letterFees, category_key: 'outsourced_fab' });
  }

  // 2. Installation labor — when a crew is assigned, personnel pricing replaces
  // the flat-rate labor (labor_cost_in_subtotal = 0), so labor is never double-counted.
  const baseLabor = p.labor_cost_in_subtotal !== undefined
    ? num(p.labor_cost_in_subtotal)
    : num(p.labor_cost);
  const installLabor = baseLabor + num(p.total_personnel_cost);
  if (installLabor > 0) {
    lines.push({ module: 'channel_letter', label: 'Installation Labor', cost: installLabor, category_key: 'inhouse_labor' });
  }

  // 3. Materials/supplies (hardware, mounting)
  const matCost = num(p.total_materials_cost) + num(p.total_supplies_cost);
  if (matCost > 0) {
    lines.push({ module: 'channel_letter', label: 'Install Materials & Supplies', cost: matCost, category_key: 'outsourced_fab' });
  }

  // 4. Equipment rental
  const eqCost = num(p.total_equipment_cost);
  if (eqCost > 0) {
    lines.push({ module: 'channel_letter', label: 'Equipment Rental', cost: eqCost, category_key: 'outsourced_services' });
  }

  // 5. Travel — was previously missing, so categorized lines didn't sum to the subtotal
  const travelCost = num(p.total_travel_cost);
  if (travelCost > 0) {
    lines.push({ module: 'channel_letter', label: 'Travel & Fuel', cost: travelCost, category_key: 'outsourced_services' });
  }

  return lines;
}

function _impl_categorizeFoundationProject(p) {
  if (!p) return [];
  const lines = [];
  const concrete = num(p.total_concrete_cost) + num(p.total_rebar_cost) + num(p.total_forming_materials_cost);
  if (concrete > 0) lines.push({ module: 'foundation', label: 'Concrete / Rebar / Forming Materials', cost: concrete, category_key: 'outsourced_fab' });
  const fLabor = num(p.total_labor_cost) + num(p.total_excavation_cost);
  if (fLabor > 0) lines.push({ module: 'foundation', label: 'Foundation Labor', cost: fLabor, category_key: 'inhouse_labor' });
  const poles = num(p.total_pole_cost) + num(p.total_pole_painting_cost);
  if (poles > 0) lines.push({ module: 'foundation', label: 'Poles & Pole Painting', cost: poles, category_key: 'outsourced_fab' });
  const eq = num(p.total_equipment_cost);
  if (eq > 0) lines.push({ module: 'foundation', label: 'Foundation Equipment Rental', cost: eq, category_key: 'outsourced_services' });

  // Foundation wall totals already contain their material, mortar and labor. Use
  // the calculated wall rows directly so tier pricing neither double-counts the
  // aggregate brick/fill fields nor treats masonry labor as purchased material.
  const wallMaterial = (p.walls || []).reduce((sum, wall) => {
    const costs = wall?.calculatedCosts || {};
    return sum + num(costs.materialCost) + num(costs.mortarCost) + num(costs.internalMaterialCost) + num(costs.internalMortarCost);
  }, 0);
  const wallLabor = (p.walls || []).reduce((sum, wall) => {
    const costs = wall?.calculatedCosts || {};
    return sum + num(costs.laborCost) + num(costs.internalLaborCost);
  }, 0);
  if (wallMaterial > 0) lines.push({ module: 'foundation', label: 'Brick / Wall / Mortar Materials', cost: wallMaterial, category_key: 'outsourced_fab' });
  if (wallLabor > 0) lines.push({ module: 'foundation', label: 'Masonry Labor', cost: wallLabor, category_key: 'outsourced_services' });

  const wallCaps = num(p.total_wall_cap_cost);
  if (wallCaps > 0) lines.push({ module: 'foundation', label: 'Wall Cap Materials', cost: wallCaps, category_key: 'outsourced_fab' });
  const cabinets = num(p.total_signage_cabinet_cost);
  if (cabinets > 0) lines.push({ module: 'foundation', label: 'Purchased Signage Cabinets', cost: cabinets, category_key: 'outsourced_fab' });
  const landscape = num(p.total_landscape_cost);
  if (landscape > 0) lines.push({ module: 'foundation', label: 'Landscape / Site Materials', cost: landscape, category_key: 'outsourced_fab' });
  return lines;
}

